def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[-1][-1]
    colors = [x for row in grid for x in row if x != bg]
    border = grid[0][-1]
    other = next((x for x in colors if x != border), border)
    value = {bg: 0, other: 1, border: 2}
    color = [bg, other, border]

    n = 0
    while n < h and any(x != bg for x in grid[n]):
        n += 1
    m = 0
    while m < len(grid[0]) and any(grid[r][m] != bg for r in range(n)):
        m += 1
    kernel = [[value[x] for x in row[:m]] for row in grid[:n]]

    out = [[0] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            total = 1 if r == 0 and c == 0 else 0
            for i in range(n):
                for j in range(m):
                    if i == 0 and j == 0:
                        continue
                    if i <= r and j <= c:
                        total += kernel[i][j] * out[r - i][c - j]
            out[r][c] = total % 3
    return [[color[x] for x in row] for row in out]
